import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Fill "war" in the Search books
    await page.locator('#q').fill('war')

    // Click the Search
    await page.locator('#go').click()
    await expect.soft(page.locator('#cart-count')).toContainText('0 items')
    await expect.soft(page.locator('#results > *')).toHaveCount(1)

    // Click the Advanced options
    await page.getByLabel('Advanced options').click()
    await expect.soft(page.locator('#cart-count')).toContainText('0 items')
    await expect.soft(page.locator('#results > *')).toHaveCount(1)
    await expect.soft(page.locator('#results')).toContainText('In stock')

    // Check the Gift wrap
    await page.locator('#gift').check()
    await expect.soft(page.locator('#cart-count')).toContainText('0 items')
    await expect.soft(page.locator('#results > *')).toHaveCount(1)
    await expect.soft(page.locator('#results')).toContainText('In stock')

    // Click the Add War and Peace to cart
    await page.getByLabel('Add War and Peace to cart').click()
    await expect.soft(page.locator('#cart-count')).toContainText('1 items')
    await expect.soft(page.locator('#results > *')).toHaveCount(1)
    await expect.soft(page.locator('#results')).toContainText('In stock')

    // Navigate to http://127.0.0.1:8177/order
    await page.goto('http://127.0.0.1:8177/order')
    await expect.soft(page.locator('#cart-count')).toContainText('0 items')

    // Click the Place order
    await page.locator('#place-order').click()
    await expect.soft(page.locator('#cart-count')).toContainText('1 items')

    // Click the Cancel (confirm)
    await page.locator('#cancel-order').click()
    await expect.soft(page.locator('#cart-count')).toContainText('1 items')
    await expect.soft(page.locator('#toast-slot')).toBeAttached()
  });
});
